import { reservationFor, usageCost } from "./quota.mjs";

export async function generateWithQuota({ request, quota, signal, generate }) {
  signal.throwIfAborted();
  const estimate = reservationFor(request);
  const reservation = await quota.reserve(estimate.amount);
  let providerDispatched = false;
  let actual;
  let result;
  try {
    signal.throwIfAborted();
    providerDispatched = true;
    result = await generate(request, { signal });
    actual = usageCost(result.usage, estimate);
    await quota.settle(reservation, actual);
  } catch (error) {
    await quota.releaseOrEnqueueRetry(reservation, {
      providerDispatched,
      actual,
    });
    if (actual === undefined) throw error;
  }
  return result;
}

import { randomUUID } from "node:crypto";
import { ChatError } from "./openai.mjs";

// Integer micro-dollars avoid floating point errors. A 2x pricing margin keeps
// this an intentionally conservative allowance rather than an invoice ledger.
// GPT-6 Luna Standard: $0.10/M input, $0.50/M output (13 October 2026).
export function reservationFor(request) {
  if (
    request.model !== "gpt-6-luna" ||
    request.service_tier !== "default" ||
    request.reasoning?.effort !== "none" ||
    request.max_output_tokens !== 1000 ||
    request.tools
  )
    throw new Error("Unsupported budget pricing configuration.");
  const bytes = Buffer.byteLength(JSON.stringify(request), "utf8");
  if (bytes > 100000)
    throw new ChatError(
      400,
      "context_too_large",
      "Please shorten the conversation and try again.",
    );
  // Byte-level text tokenizers cannot emit more text tokens than UTF-8 bytes.
  // Count the entire serialized request plus generous framing overhead.
  const inputBound = bytes + 4096;
  return { inputBound, amount: Math.ceil(inputBound / 5 + 1000) };
}

export function usageCost(usage, reservation) {
  if (
    !Number.isSafeInteger(usage?.input_tokens) ||
    usage.input_tokens < 0 ||
    usage.input_tokens > reservation.inputBound ||
    !Number.isSafeInteger(usage?.output_tokens) ||
    usage.output_tokens < 0 ||
    usage.output_tokens > 1000
  )
    return reservation.amount;
  // Treat every input token as uncached: provider cache discounts only save money.
  return Math.min(
    reservation.amount,
    Math.ceil(usage.input_tokens / 5 + usage.output_tokens),
  );
}

export function periodsAt(time) {
  const date = new Date(time);
  if (!Number.isFinite(date.getTime())) throw new Error("Invalid quota clock.");
  const day = date.toISOString().slice(0, 10);
  const month = day.slice(0, 7);
  return {
    day,
    month,
    dayReset: Date.UTC(
      date.getUTCFullYear(),
      date.getUTCMonth(),
      date.getUTCDate() + 1,
    ),
    monthReset: Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 1),
  };
}

export const RESERVE_SCRIPT = `
local daily = tonumber(redis.call('GET', KEYS[1]) or '0')
local monthly = tonumber(redis.call('GET', KEYS[2]) or '0')
local amount = tonumber(ARGV[3])
if not daily or not monthly or daily < 0 or monthly < 0 then return redis.error_reply('Invalid quota state') end
if redis.call('EXISTS', KEYS[3]) ~= 0 then return redis.error_reply('Duplicate reservation') end
if daily >= tonumber(ARGV[1]) then return {0, 'daily'} end
if monthly + amount > tonumber(ARGV[2]) then return {0, 'monthly'} end
redis.call('INCR', KEYS[1])
redis.call('INCRBY', KEYS[2], amount)
redis.call('EXPIREAT', KEYS[1], ARGV[4])
redis.call('EXPIREAT', KEYS[2], ARGV[5])
redis.call('HSET', KEYS[3], 'amount', amount, 'settled', 0)
redis.call('EXPIREAT', KEYS[3], ARGV[5])
return {1, daily + 1, monthly + amount}
`;

export const SETTLE_SCRIPT = `
if redis.call('EXISTS', KEYS[1]) == 0 or redis.call('EXISTS', KEYS[2]) == 0 then
  return redis.error_reply('Missing quota state')
end
if redis.call('HGET', KEYS[2], 'settled') == '1' then return 0 end
local reserved = tonumber(redis.call('HGET', KEYS[2], 'amount'))
local actual = tonumber(ARGV[1])
local monthly = tonumber(redis.call('GET', KEYS[1]))
if not reserved or not monthly or actual < 0 or actual > reserved or monthly < reserved then
  return redis.error_reply('Invalid settlement')
end
redis.call('DECRBY', KEYS[1], reserved - actual)
redis.call('HSET', KEYS[2], 'settled', 1)
return 1
`;

// Retry records contain accounting metadata only; never prompts or responses.
export const ENQUEUE_SETTLEMENT_SCRIPT = `
if redis.call('EXISTS', KEYS[1]) == 0 then return redis.error_reply('Missing reservation') end
if redis.call('HGET', KEYS[1], 'settled') == '1' then return 0 end
local reserved = tonumber(redis.call('HGET', KEYS[1], 'amount'))
local actual = tonumber(ARGV[1])
if not reserved or not actual or actual < 0 or actual > reserved then return redis.error_reply('Invalid retry') end
redis.call('ZADD', KEYS[2], 'NX', ARGV[2], ARGV[3])
return 1
`;

export const CLAIM_SETTLEMENTS_SCRIPT = `
local jobs = redis.call('ZRANGEBYSCORE', KEYS[1], '-inf', ARGV[1], 'LIMIT', 0, ARGV[3])
for _, job in ipairs(jobs) do redis.call('ZADD', KEYS[1], ARGV[2], job) end
return jobs
`;

export const RETRY_FAILURE_SCRIPT = `
if redis.call('EXISTS', KEYS[1]) == 0 or redis.call('HGET', KEYS[1], 'settled') == '1' then
  redis.call('ZREM', KEYS[2], ARGV[1])
  return 0
end
local attempts = redis.call('HINCRBY', KEYS[1], 'retry_attempts', 1)
if attempts >= 5 then
  redis.call('ZADD', KEYS[3], ARGV[2], ARGV[1])
  redis.call('EXPIRE', KEYS[3], 7776000)
  redis.call('ZREMRANGEBYSCORE', KEYS[3], '-inf', tonumber(ARGV[2]) - 7776000000)
  redis.call('ZREM', KEYS[2], ARGV[1])
  return -1
end
redis.call('ZADD', KEYS[2], 'XX', tonumber(ARGV[2]) + math.min(300000, 30000 * (2 ^ (attempts - 1))), ARGV[1])
return attempts
`;

const unavailable = () =>
  new ChatError(
    503,
    "quota_unavailable",
    "The assistant is temporarily paused to protect its usage allowance. Please try later or contact Harsh.",
    60,
  );

export class RedisQuota {
  constructor({
    url,
    token,
    dailyLimit = 200,
    monthlyBudgetMicros = 1000000,
    namespace = "portfolio-ai:v1",
    clock = Date.now,
    fetchImpl = fetch,
  }) {
    this.configured = Boolean(url && token);
    this.url = url;
    this.token = token;
    this.dailyLimit = dailyLimit;
    this.monthlyBudgetMicros = monthlyBudgetMicros;
    this.namespace = namespace;
    this.clock = clock;
    this.fetchImpl = fetchImpl;
    if (
      !Number.isSafeInteger(dailyLimit) ||
      dailyLimit < 1 ||
      !Number.isSafeInteger(monthlyBudgetMicros) ||
      monthlyBudgetMicros < 1 ||
      !/^[a-zA-Z0-9:_-]{1,100}$/.test(namespace)
    )
      throw new Error("Invalid quota configuration.");
    if (url) {
      const parsed = new URL(url);
      if (
        parsed.protocol !== "https:" ||
        parsed.username ||
        parsed.password ||
        !/^[a-z0-9-]+\.upstash\.io$/.test(parsed.hostname) ||
        parsed.pathname !== "/" ||
        parsed.search ||
        parsed.hash
      )
        throw new Error("Use the HTTPS Upstash REST endpoint.");
    }
  }
  async command(command) {
    if (!this.configured) throw unavailable();
    try {
      const response = await this.fetchImpl(this.url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${this.token}`,
        },
        body: JSON.stringify(command),
        signal: AbortSignal.timeout(3000),
      });
      if (!response.ok) throw new Error("Quota service unavailable.");
      const body = await response.json();
      if (body.error || !Object.hasOwn(body, "result"))
        throw new Error("Quota command failed.");
      return body.result;
    } catch {
      throw unavailable();
    }
  }
  async reserve(amount) {
    if (!Number.isSafeInteger(amount) || amount < 1) throw unavailable();
    const time = this.clock();
    const periods = periodsAt(time);
    // A hash tag co-locates every key for Redis deployments with clustering.
    const prefix = `{${this.namespace}}`;
    const dayKey = `${prefix}:day:${periods.day}`;
    const monthKey = `${prefix}:month:${periods.month}`;
    const requestKey = `${prefix}:request:${randomUUID()}`;
    const result = await this.command([
      "EVAL",
      RESERVE_SCRIPT,
      3,
      dayKey,
      monthKey,
      requestKey,
      this.dailyLimit,
      this.monthlyBudgetMicros,
      amount,
      Math.ceil(periods.dayReset / 1000) + 172800,
      Math.ceil(periods.monthReset / 1000) + 604800,
    ]);
    if (
      Array.isArray(result) &&
      result[0] === 0 &&
      ["daily", "monthly"].includes(result[1])
    ) {
      const daily = result[1] === "daily";
      throw new ChatError(
        429,
        daily ? "daily_limit" : "monthly_budget",
        daily
          ? "The assistant has reached today's question allowance. Please return tomorrow or contact Harsh."
          : "The assistant has reached its monthly usage allowance. Please explore the projects or contact Harsh.",
        Math.max(
          1,
          Math.ceil(
            ((daily ? periods.dayReset : periods.monthReset) - time) / 1000,
          ),
        ),
      );
    }
    if (
      !Array.isArray(result) ||
      result[0] !== 1 ||
      !Number.isSafeInteger(result[1]) ||
      !Number.isSafeInteger(result[2]) ||
      result[1] < 1 ||
      result[1] > this.dailyLimit ||
      result[2] < amount ||
      result[2] > this.monthlyBudgetMicros
    )
      throw unavailable();
    return { monthKey, requestKey, amount };
  }
  async snapshot() {
    const periods = periodsAt(this.clock());
    const prefix = `{${this.namespace}}`;
    const result = await this.command([
      "MGET",
      `${prefix}:day:${periods.day}`,
      `${prefix}:month:${periods.month}`,
    ]);
    if (
      !Array.isArray(result) ||
      result.length !== 2 ||
      result.some((v) => v !== null && !/^[0-9]+$/.test(String(v)))
    )
      throw unavailable();
    const [requestsUsed, budgetUsedMicros] = result.map((v) => Number(v || 0));
    if (![requestsUsed, budgetUsedMicros].every(Number.isSafeInteger))
      throw unavailable();
    const backlog = await Promise.all([
      this.command(["ZCARD", `${prefix}:settlement-retries`]),
      this.command(["ZCARD", `${prefix}:settlement-dead-letters`]),
    ]);
    if (!backlog.every((value) => Number.isSafeInteger(value) && value >= 0))
      throw unavailable();
    return {
      day: periods.day,
      month: periods.month,
      requestsUsed,
      dailyLimit: this.dailyLimit,
      requestsRemaining: Math.max(0, this.dailyLimit - requestsUsed),
      budgetUsedUsd: budgetUsedMicros / 1000000,
      monthlyBudgetUsd: this.monthlyBudgetMicros / 1000000,
      budgetRemainingUsd:
        Math.max(0, this.monthlyBudgetMicros - budgetUsedMicros) / 1000000,
      dailyResetUtc: new Date(periods.dayReset).toISOString(),
      monthlyResetUtc: new Date(periods.monthReset).toISOString(),
      settlementRetriesQueued: backlog[0],
      settlementDeadLetters: backlog[1],
    };
  }
  async releaseOrEnqueueRetry(reservation, { providerDispatched, actual }) {
    if (providerDispatched && actual === undefined) return "retained";
    const amount = providerDispatched ? actual : 0;
    if (!providerDispatched) {
      try {
        await this.settle(reservation, 0);
        return "released";
      } catch {
        /* A failed rollback becomes a durable zero-cost settlement. */
      }
    }
    if (
      !Number.isSafeInteger(amount) ||
      amount < 0 ||
      amount > reservation.amount
    )
      throw unavailable();
    const job = JSON.stringify({ ...reservation, actual: amount });
    const result = await this.command([
      "EVAL",
      ENQUEUE_SETTLEMENT_SCRIPT,
      2,
      reservation.requestKey,
      `{${this.namespace}}:settlement-retries`,
      amount,
      this.clock(),
      job,
    ]);
    if (result !== 0 && result !== 1) throw unavailable();
    return result === 1 ? "queued" : "settled";
  }
  async retrySettlements({ limit = 5 } = {}) {
    if (!Number.isSafeInteger(limit) || limit < 1 || limit > 20)
      throw unavailable();
    const prefix = `{${this.namespace}}`;
    const queue = `${prefix}:settlement-retries`;
    const now = this.clock();
    const jobs = await this.command([
      "EVAL",
      CLAIM_SETTLEMENTS_SCRIPT,
      1,
      queue,
      now,
      now + Math.max(120000, limit * 12000 + 30000),
      limit,
    ]);
    if (!Array.isArray(jobs) || jobs.length > limit) throw unavailable();
    const report = {
      claimed: jobs.length,
      settled: 0,
      failed: 0,
      deadLettered: 0,
    };
    for (const encoded of jobs) {
      let job;
      try {
        job = JSON.parse(encoded);
      } catch {
        throw unavailable();
      }
      if (
        typeof job.monthKey !== "string" ||
        !job.monthKey.startsWith(prefix) ||
        !/^:month:\d{4}-\d{2}$/.test(job.monthKey.slice(prefix.length)) ||
        typeof job.requestKey !== "string" ||
        !job.requestKey.startsWith(prefix) ||
        !/^:request:[a-f0-9-]{36}$/.test(job.requestKey.slice(prefix.length)) ||
        !Number.isSafeInteger(job.amount) ||
        job.amount < 1 ||
        !Number.isSafeInteger(job.actual) ||
        job.actual < 0 ||
        job.actual > job.amount
      )
        throw unavailable();
      try {
        // Expired reservations belong to an expired accounting window.
        const exists = await this.command(["EXISTS", job.requestKey]);
        if (exists !== 0 && exists !== 1) throw unavailable();
        if (exists === 1) await this.settle(job, job.actual);
        await this.command(["ZREM", queue, encoded]);
        report.settled++;
      } catch {
        const status = await this.command([
          "EVAL",
          RETRY_FAILURE_SCRIPT,
          3,
          job.requestKey,
          queue,
          `${prefix}:settlement-dead-letters`,
          encoded,
          this.clock(),
        ]);
        if (status === -1) report.deadLettered++;
        else if (Number.isSafeInteger(status) && status >= 0 && status < 5)
          report.failed++;
        else throw unavailable();
      }
    }
    return report;
  }
  async settle(reservation, actual) {
    if (
      !Number.isSafeInteger(actual) ||
      actual < 0 ||
      actual > reservation.amount
    )
      throw unavailable();
    const result = await this.command([
      "EVAL",
      SETTLE_SCRIPT,
      2,
      reservation.monthKey,
      reservation.requestKey,
      actual,
    ]);
    if (result !== 0 && result !== 1) throw unavailable();
  }
}

import { createHash, randomUUID } from "node:crypto";
import { ChatError } from "./openai.mjs";

// One atomic admission across every Vercel instance. Client addresses are hashed;
// no conversation text or raw IP addresses enter these short-lived keys.
export const ADMIT_SCRIPT = `
local client = tonumber(redis.call('GET', KEYS[1]) or '0')
local global = tonumber(redis.call('GET', KEYS[2]) or '0')
if not client or not global or client < 0 or global < 0 then return {-1, 0} end
local now = tonumber(ARGV[1])
redis.call('ZREMRANGEBYSCORE', KEYS[3], '-inf', now)
if client >= tonumber(ARGV[2]) or global >= tonumber(ARGV[3]) then
  return {0, tonumber(ARGV[6])}
end
if redis.call('ZCARD', KEYS[3]) >= tonumber(ARGV[4]) then return {0, 5} end
redis.call('INCR', KEYS[1])
redis.call('INCR', KEYS[2])
redis.call('PEXPIRE', KEYS[1], ARGV[5])
redis.call('PEXPIRE', KEYS[2], ARGV[5])
redis.call('ZADD', KEYS[3], now + tonumber(ARGV[7]), ARGV[8])
redis.call('PEXPIRE', KEYS[3], tonumber(ARGV[7]) * 2)
return {1, 0}
`;

function unavailable() {
  return new ChatError(
    503,
    "quota_unavailable",
    "The assistant’s usage protection is temporarily unavailable. Please try again later or contact Harsh.",
  );
}

export class RedisAdmission {
  constructor({
    store,
    clientLimit = 10,
    globalLimit = 60,
    concurrentLimit = 3,
    windowMs = 600000,
    leaseMs = 120000,
    clock = Date.now,
  }) {
    if (
      ![clientLimit, globalLimit, concurrentLimit, windowMs, leaseMs].every(
        (n) => Number.isSafeInteger(n) && n > 0,
      )
    )
      throw new Error("Invalid admission configuration.");
    this.store = store;
    this.clientLimit = clientLimit;
    this.globalLimit = globalLimit;
    this.concurrentLimit = concurrentLimit;
    this.windowMs = windowMs;
    this.leaseMs = leaseMs;
    this.clock = clock;
  }
  async acquire(client) {
    if (!this.store.configured) throw unavailable();
    const now = this.clock();
    const bucket = Math.floor(now / this.windowMs);
    const retryAfter = Math.max(
      1,
      Math.ceil(((bucket + 1) * this.windowMs - now) / 1000),
    );
    const prefix = `{${this.store.namespace}}:admission`;
    const identity = createHash("sha256")
      .update(String(client || "unknown"))
      .digest("hex");
    const lease = { key: `${prefix}:active`, id: randomUUID() };
    let result;
    try {
      result = await this.store.command([
        "EVAL",
        ADMIT_SCRIPT,
        3,
        `${prefix}:client:${identity}:${bucket}`,
        `${prefix}:global:${bucket}`,
        lease.key,
        now,
        this.clientLimit,
        this.globalLimit,
        this.concurrentLimit,
        this.windowMs * 2,
        retryAfter,
        this.leaseMs,
        lease.id,
      ]);
    } catch {
      throw unavailable();
    }
    if (
      !Array.isArray(result) ||
      result.length !== 2 ||
      !Number.isSafeInteger(result[1]) ||
      result[1] < 0
    )
      throw unavailable();
    if (result[0] === 0 && result[1] > 0)
      throw new ChatError(
        429,
        "rate_limit",
        "The assistant is busy. Please try again shortly or use the contact links.",
        result[1],
      );
    if (result[0] !== 1 || result[1] !== 0) throw unavailable();
    return lease;
  }
  async release(lease) {
    const result = await this.store.command(["ZREM", lease.key, lease.id]);
    if (result !== 0 && result !== 1) throw unavailable();
  }
}

import {
  ChatError,
  validateMessages,
  buildRequest,
  sourceLinks,
} from "./openai.mjs";
import { reservationFor, usageCost } from "./quota.mjs";

export const VOICE_MODELS = Object.freeze({
  transcription: "gpt-4o-mini-transcribe",
  speech: "tts-1",
  voice: "nova",
});
// Integer microdollars, including the same 2x safety margin as text chat.
// Transcription: 16k context + 2k output at $1.25/$5 per million tokens.
// Speech: at most 900 characters at $15 per million characters.
const TRANSCRIPTION_BOUND = 60000;
const TEXT_BOUND = Math.ceil(104096 / 5 + 1000);
const SPEECH_BOUND = 900 * 30;
export const VOICE_RESERVATION =
  TRANSCRIPTION_BOUND + TEXT_BOUND + SPEECH_BOUND;

function invalidAudio() {
  return new ChatError(
    400,
    "invalid_audio",
    "Record a short question (up to 20 seconds) and try again.",
  );
}

export function validateVoice(body) {
  if (
    !body ||
    typeof body.audio !== "string" ||
    body.audio.length > 854000 ||
    !/^[A-Za-z0-9+/]+={0,2}$/.test(body.audio)
  )
    throw invalidAudio();
  const audio = Buffer.from(body.audio, "base64");
  if (
    audio.toString("base64") !== body.audio ||
    audio.length < 3244 ||
    audio.length > 640044
  )
    throw invalidAudio();
  if (
    audio.toString("ascii", 0, 4) !== "RIFF" ||
    audio.readUInt32LE(4) !== audio.length - 8 ||
    audio.toString("ascii", 8, 16) !== "WAVEfmt " ||
    audio.readUInt32LE(16) !== 16 ||
    audio.readUInt16LE(20) !== 1 ||
    audio.readUInt16LE(22) !== 1 ||
    audio.readUInt32LE(24) !== 16000 ||
    audio.readUInt32LE(28) !== 32000 ||
    audio.readUInt16LE(32) !== 2 ||
    audio.readUInt16LE(34) !== 16 ||
    audio.toString("ascii", 36, 40) !== "data" ||
    audio.readUInt32LE(40) !== audio.length - 44 ||
    audio.length % 2
  )
    throw invalidAudio();
  let energy = 0;
  for (let i = 44; i < audio.length; i += 2)
    energy += (audio.readInt16LE(i) / 32768) ** 2;
  if (Math.sqrt(energy / ((audio.length - 44) / 2)) < 0.001)
    throw new ChatError(
      400,
      "no_speech",
      "No speech was detected. Try again closer to your microphone.",
    );
  const history = body.messages ?? [];
  if (!Array.isArray(history) || history.length > 8 || history.length % 2)
    throw new ChatError(
      400,
      "invalid_history",
      "Please start a new conversation.",
    );
  validateMessages({
    messages: [...history, { role: "user", content: "voice question" }],
  });
  return { audio, history };
}

async function boundedBytes(response, max) {
  const reader = response.body?.getReader();
  if (!reader) throw new Error("Empty audio response");
  const chunks = [];
  let length = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      length += value.length;
      if (length > max) throw new Error("Audio response too large");
      chunks.push(Buffer.from(value));
    }
  } finally {
    await reader.cancel().catch(() => {});
  }
  if (!length) throw new Error("Empty response");
  return Buffer.concat(chunks);
}

export async function transcribe(audio, { apiKey, signal, fetchImpl = fetch }) {
  const form = new FormData();
  form.set("file", new Blob([audio], { type: "audio/wav" }), "question.wav");
  form.set("model", VOICE_MODELS.transcription);
  form.set("response_format", "json");
  const response = await fetchImpl(
    "https://api.openai.com/v1/audio/transcriptions",
    {
      method: "POST",
      headers: { Authorization: `Bearer ${apiKey}` },
      body: form,
      signal: AbortSignal.any([signal, AbortSignal.timeout(12000)]),
    },
  );
  if (!response.ok) throw new Error("Transcription unavailable");
  return JSON.parse((await boundedBytes(response, 64000)).toString("utf8"));
}

export async function speak(input, { apiKey, signal, fetchImpl = fetch }) {
  const response = await fetchImpl("https://api.openai.com/v1/audio/speech", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: VOICE_MODELS.speech,
      voice: VOICE_MODELS.voice,
      input,
      response_format: "mp3",
    }),
    signal: AbortSignal.any([signal, AbortSignal.timeout(15000)]),
  });
  if (!response.ok) throw new Error("Speech unavailable");
  return boundedBytes(response, 1500000);
}

function transcriptionCost(usage) {
  if (
    !Number.isSafeInteger(usage?.input_tokens) ||
    usage.input_tokens < 0 ||
    usage.input_tokens > 16000 ||
    !Number.isSafeInteger(usage?.output_tokens) ||
    usage.output_tokens < 0 ||
    usage.output_tokens > 2000
  )
    return TRANSCRIPTION_BOUND;
  return Math.ceil(usage.input_tokens * 2.5 + usage.output_tokens * 10);
}

export function spokenText(answer) {
  const text = answer
    .replace(/https?:\/\/\S+/g, "")
    .replace(/[*#`]/g, "")
    .trim();
  if (text.length <= 900) return text;
  const end = text.slice(0, 897).lastIndexOf(". ");
  return end > 400
    ? text.slice(0, end + 1)
    : text.slice(0, 897).trimEnd() + "…";
}

export async function generateVoice({
  audio,
  history,
  quota,
  signal,
  model,
  generate,
  transcribeAudio,
  speakAudio,
}) {
  signal.throwIfAborted();
  const reservation = await quota.reserve(VOICE_RESERVATION);
  let completed = 0,
    inFlight = 0,
    dispatched = false,
    result,
    failure;
  try {
    signal.throwIfAborted();
    inFlight = TRANSCRIPTION_BOUND;
    dispatched = true;
    const transcription = await transcribeAudio(audio, { signal });
    completed += transcriptionCost(transcription.usage);
    inFlight = 0;
    signal.throwIfAborted();
    const transcript =
      typeof transcription.text === "string" ? transcription.text.trim() : "";
    if (!transcript)
      throw new ChatError(
        400,
        "no_speech",
        "No speech was detected. Please try again.",
      );
    const messages = validateMessages({
      messages: [...history, { role: "user", content: transcript }],
    });
    const request = buildRequest(messages, model);
    request.instructions +=
      "\nThis is a spoken conversation. Answer naturally in at most 90 words, without markdown, URLs, or reading out source labels. Keep all existing factual and portfolio-only boundaries.";
    const estimate = reservationFor(request);
    if (estimate.amount > TEXT_BOUND) throw new Error("Voice context limit");
    signal.throwIfAborted();
    inFlight = estimate.amount;
    const reply = await generate(messages, signal, request);
    completed += usageCost(reply.usage, estimate);
    inFlight = 0;
    signal.throwIfAborted();
    if (typeof reply.answer !== "string" || !reply.answer.trim())
      throw new Error("Invalid reply");
    result = { transcript, answer: reply.answer, sources: sourceLinks(reply) };
    const input = spokenText(reply.answer);
    inFlight = input.length * 30;
    try {
      const audioOutput = await speakAudio(input, { signal });
      if (!audioOutput?.length) throw new Error("Empty speech");
      result.audio = Buffer.from(audioOutput).toString("base64");
      result.audioType = "audio/mpeg";
    } catch {
      signal.throwIfAborted();
      result.audioError = "Audio is unavailable. Your written answer is below.";
    }
    completed += inFlight;
    inFlight = 0;
  } catch (error) {
    failure = error;
  }
  const actual = Math.min(reservation.amount, completed + inFlight);
  try {
    await quota.settle(reservation, actual);
  } catch {
    await quota.releaseOrEnqueueRetry(reservation, {
      providerDispatched: dispatched,
      actual,
    });
  }
  if (failure) throw failure;
  signal.throwIfAborted();
  return result;
}

